        /**
         * Formats a duration to milliseconds.
         */
        double duration_to_ms(const Duration d) {
            return static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(d).count()) / 1000.0;
        }

        std::string format_duration_human(const Duration d) {
            const double ms = duration_to_ms(d);
            std::ostringstream ss;
            if (ms >= 1000.0) {
                ss << std::fixed << std::setprecision(3) << (ms / 1000.0) << " s";
            } else {
                ss << std::fixed << std::setprecision(2) << ms << " ms";
            }
            return ss.str();
        }

        std::optional<Duration> total_estimated_savings(
            const std::vector<Suggestion>& suggestions
        ) {
            Duration total = Duration::zero();
            for (const auto& suggestion : suggestions) {
                if (suggestion.estimated_savings_evidence == EvidenceKind::Unavailable) {
                    return std::nullopt;
                }
                const auto sum = utils::checked_add_duration(
                    total,
                    suggestion.estimated_savings
                );
                if (!sum.has_value()) {
                    return std::nullopt;
                }
                total = *sum;
            }
            return total;
        }

        std::string format_estimated_savings(const Suggestion& suggestion) {
            if (suggestion.estimated_savings_evidence == EvidenceKind::Unavailable) {
                return "unavailable";
            }
            return format_duration_human(suggestion.estimated_savings);
        }

        bool has_cache_data(const analyzers::CacheDistributionAnalysisResult& cache) {
            return cache.compile_requests > 0 ||
                cache.executed_compilations > 0 ||
                cache.compilations > 0 ||
                cache.cache_hits > 0 ||
                cache.cache_misses > 0 ||
                !cache.metric_capabilities.empty();
        }

        /**
         * Escapes HTML special characters.
         */
        std::string escape_html(const std::string& text) {
            std::string result;
            result.reserve(static_cast<std::size_t>(static_cast<double>(text.size()) * 1.1));
            for (const char c : text) {
                switch (c) {
                case '&': result += "&amp;"; break;
                case '<': result += "&lt;"; break;
                case '>': result += "&gt;"; break;
                case '"': result += "&quot;"; break;
                case '\'': result += "&#39;"; break;
                default: result += c; break;
                }
            }
            return result;
        }

        std::string format_markdown_simple(const std::string& markdown) {
            std::string html;
            std::istringstream stream(markdown);
            std::string line;
            bool in_list = false;
            bool in_code_block = false;
            std::string code_block_content;

            while (std::getline(stream, line)) {
                if (line.starts_with("```")) {
                    if (in_code_block) {
                        html += R"(<pre class="code-block" style="margin: 6px 0; padding: 12px; background: var(--bg-secondary); border-radius: 6px; border-left: 3px solid var(--accent-color); overflow-x: auto;">)";
                        html += escape_html(code_block_content);
                        html += "</pre>\n";
                        code_block_content.clear();
                        in_code_block = false;
                    } else {
                        if (in_list) {
                            html += "</ul>\n";
                            in_list = false;
                        }
                        in_code_block = true;
                    }
                    continue;
                }

                if (in_code_block) {
                    code_block_content += line + "\n";
                    continue;
                }

                if (line.empty()) {
                    if (in_list) {
                        html += "</ul>\n";
                        in_list = false;
                    }
                    continue;
                }

                if (line.starts_with("  - ") || line.starts_with("- ")) {
                    if (!in_list) {
                        html += "<ul style=\"margin: 8px 0; padding-left: 24px;\">\n";
                        in_list = true;
                    }
                    const std::string item = line.substr(line.find("- ") + 2);
                    html += "<li>" + escape_html(item) + "</li>\n";
                    continue;
                }

                if (in_list) {
                    html += "</ul>\n";
                    in_list = false;
                }

                std::string processed = line;
                size_t pos = 0;
                while ((pos = processed.find("**", pos)) != std::string::npos) {
                    if (const size_t end_pos = processed.find("**", pos + 2); end_pos != std::string::npos) {
                        const std::string bold_text = processed.substr(pos + 2, end_pos - pos - 2);
                        const std::string replacement = "<strong>" + bold_text + "</strong>";
                        processed.replace(pos, end_pos - pos + 2, replacement);
                        pos += replacement.length();
                    } else {
                        break;
                    }
                }

                html += "<p style=\"margin: 2px 0;\">" + processed + "</p>\n";
            }

            if (in_list) {
                html += "</ul>\n";
            }

            if (in_code_block && !code_block_content.empty()) {
                html += R"(<pre class="code-block" style="margin: 6px 0; padding: 12px; background: var(--bg-secondary); border-radius: 6px; border-left: 3px solid var(--accent-color); overflow-x: auto;">)";
                html += escape_html(code_block_content);
                html += "</pre>\n";
            }

            return html;
        }

        std::size_t count_lines(const std::string& text) {
            if (text.empty()) {
                return 0;
            }
            return static_cast<std::size_t>(std::count(text.begin(), text.end(), '\n')) + 1;
        }

        std::string truncate_lines(const std::string& text, const std::size_t max_lines) {
            if (max_lines == 0 || text.empty()) {
                return {};
            }
            std::size_t line_count = 0;
            std::size_t pos = 0;
            for (; pos < text.size(); ++pos) {
                if (text[pos] == '\n') {
                    ++line_count;
                    if (line_count >= max_lines) {
                        ++pos;
                        break;
                    }
                }
            }
            return text.substr(0, pos);
        }

        /**
         * Replaces multiple placeholders in a template string.
         */
        std::string replace_placeholders(const std::string_view tmpl,
                                        const std::vector<std::pair<std::string, std::string>>& replacements) {
            std::string result(tmpl);
            for (const auto& [placeholder, value] : replacements) {
                size_t pos = 0;
                while ((pos = result.find(placeholder, pos)) != std::string::npos) {
                    result.replace(pos, placeholder.length(), value);
                    pos += value.length();
                }
            }
            return result;
        }

        /**
         * Escapes CSV special characters.
         */
        std::string escape_csv(const std::string& text) {
            if (text.find_first_of(",\"\n\r") == std::string::npos) {
                return text;
            }
            std::string result = "\"";
            for (const char c : text) {
                if (c == '"') {
                    result += "\"\"";
                } else {
                    result += c;
                }
            }
            result += "\"";
            return result;
        }

        std::string csv_number(const double value, const int precision = 3) {
            std::ostringstream stream;
            stream << std::fixed << std::setprecision(precision) << value;
            return stream.str();
        }

        std::string csv_duration(const Duration duration, const bool include_timing) {
            return include_timing ? csv_number(duration_to_ms(duration)) : "excluded";
        }

        std::string csv_optional_duration(
            const std::optional<Duration>& duration,
            const bool include_timing
        ) {
            if (!duration.has_value()) {
                return "unavailable";
            }
            return csv_duration(*duration, include_timing);
        }

        std::string csv_optional_uint64(const std::optional<std::uint64_t>& value) {
            return value.has_value() ? std::to_string(*value) : "unavailable";
        }

        void write_csv_row(std::ostream& stream, const std::vector<std::string>& fields) {
            for (std::size_t index = 0; index < fields.size(); ++index) {
                if (index != 0) {
                    stream << ',';
                }
                stream << escape_csv(fields[index]);
            }
            stream << "\r\n";
        }

        std::string escape_markdown_cell(const std::string& value) {
            std::string result;
            result.reserve(value.size());
            for (const char character : value) {
                if (character == '|') {
                    result += "\\|";
                } else if (character == '\n' || character == '\r') {
                    result += ' ';
                } else {
                    result += character;
                }
            }
            return result;
        }

        Result<void, Error> write_csv_file(
            const fs::path& path,
            const std::vector<std::string>& header,
            const std::function<void(std::ostream&)>& write_rows
        ) {
            std::ofstream file(path);
            if (!file.is_open()) {
                return Result<void, Error>::failure(
                    Error(ErrorCode::IoError, "Failed to open CSV file for writing: " + path.string())
                );
            }
            write_csv_row(file, header);
            write_rows(file);
            if (!file.good()) {
                return Result<void, Error>::failure(
                    Error(ErrorCode::IoError, "Failed while writing CSV file: " + path.string())
                );
            }
            return Result<void, Error>::success();
        }

        std::string application_mode_label(const Suggestion& suggestion) {
            if (suggestion.application_summary && !suggestion.application_summary->empty()) {
                return *suggestion.application_summary;
            }
            switch (resolve_application_mode(suggestion)) {
                case SuggestionApplicationMode::DirectEdits:
                    return "Direct Edits";
                case SuggestionApplicationMode::ExternalRefactor:
                    return "Refactor Tool";
                case SuggestionApplicationMode::Advisory:
                    return "Manual Review";
            }
            return "Manual Review";
        }

        std::string application_mode_note(const Suggestion& suggestion) {
            if (suggestion.application_guidance && !suggestion.application_guidance->empty()) {
                return *suggestion.application_guidance;
            }
            switch (resolve_application_mode(suggestion)) {
                case SuggestionApplicationMode::DirectEdits:
                    return "BHA can apply this suggestion with direct text edits, rebuild-validate the change, and roll back from backup if validation fails.";
                case SuggestionApplicationMode::ExternalRefactor:
                    return "BHA applies this through the semantic refactor tool, rebuild-validates the result, and rolls back from backup if validation fails.";
                case SuggestionApplicationMode::Advisory:
                    return "This suggestion is intentionally advisory. Review and apply it manually.";
            }
            return "This suggestion is intentionally advisory. Review and apply it manually.";
        }

